import{z as o,x as n,o as E,c as s,q as e,j as i,D as t,d as l,s as r,S as _}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"动态条件相关 DCC","description":"","frontmatter":{"title":"动态条件相关 DCC","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/dcc.md","filePath":"quant/dcc.md","lastUpdated":1791063341000}'),A={name:"quant/dcc.md"};function p(B,a,d,D,c,m){const C=n("Mermaid");return E(),s("div",null,[a[2]||(a[2]=e('<h1 id="动态条件相关-dcc" tabindex="-1">动态条件相关 DCC <a class="header-anchor" href="#动态条件相关-dcc" aria-label="Permalink to &quot;动态条件相关 DCC&quot;">​</a></h1><div class="epigraph"><p>先让每个资产有自己的条件方差，再让标准化残差的相关矩阵做一次低维的均值回复；参数个数不随资产对数二次爆炸，相关却仍能在压力日升高。</p><footer>—— Engle, Dynamic Conditional Correlation, Journal of Business &amp; Economic Statistics 2002</footer></div><p>多元波动要同时交代两件事：各自时变的方差，以及它们之间时变的相关。Bollerslev 的常相关模型（CCC）把第二件冻结成常数矩阵，危机里明显不够。BEKK 一类把整块协方差做成 GARCH，参数随维度平方涨，估计不稳。Engle 的动态条件相关（DCC）把问题拆开：一元 GARCH 管对角，标准化残差上一个两参数的动态管相关。Tse–Tsui 几乎同时给出相近的时变相关 GARCH。本篇写 DCC 估的对象、两步准似然，以及它与 <a href="/quant/copula">Copula</a> 在尾部上的分工。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记收益 \\(r_t=H_t^{1/2}\\varepsilon_t\\)，\\(\\varepsilon_t\\) 白噪声，\\(H_t\\) 为条件协方差。分解 \\(H_t=D_t R_t D_t\\)，其中 \\(D_t=\\mathrm{diag}(\\sigma_{1t},\\ldots,\\sigma_{dt})\\)，\\(\\sigma_{it}^2\\) 是一元条件方差，\\(R_t\\) 是条件相关。<span class="marginnote">术语翻译：条件相关就是「已知今天的市场状态后，明天两只资产同涨同跌的程度」；CCC（常相关）进一步假设这个程度是一张不随时间变的老照片。DCC 做的事，就是让这张照片每天按最新数据重新冲洗一次，但只用两三个参数，避免参数爆炸。</span>CCC 令 \\(R_t=R\\)。经验上，股权相关在下跌日升高，汇率、信用利差也有「坏时更黏」的现象。需要 \\(R_t\\) 随数据动，但不能为每个矩阵元配一套 GARCH。</p><p>还要保证 \\(R_t\\) 对每个 \\(t\\) 都是相关矩阵：对称、单位对角、正定。任意对 \\(H_t\\) 做 GARCH 不自动满足这一点。DCC 用一个伪相关矩阵 \\(Q_t\\) 做均值回复，再标准化成 \\(R_t\\)，把正定性与单位对角交给构造，而不是交给约束优化碰运气。</p><h3 id="维数灾难" tabindex="-1">维数灾难 <a class="header-anchor" href="#维数灾难" aria-label="Permalink to &quot;维数灾难&quot;">​</a></h3><p>\\(d\\) 个资产的无约束协方差 GARCH 有 \\(O(d^2)\\) 甚至 \\(O(d^4)\\) 参数。一元 GARCH(1,1) 只需 \\(3d\\) 量级，若相关动态只有少数几个参数，高维才可估。Engle 的标量 DCC 用两个参数 \\(a,b\\) 驱动整个 \\(Q_t\\)，换来可估计性，也换来「所有相关对共用同一回复速度」的刚性。这是方法要显式承认的偏误，不是实现细节。</p><p><span class="marginnote">相关升高与波动升高经常同时出现。若先不对各序列做 GARCH，直接对收益算滚动相关，波动聚类会冒充相关变动。DCC 先除以 \\(\\sigma_{it}\\)，就是为了问标准化残差是否更一起动，而不是问「大家都在大波动」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>第一步。</strong> 对每个 \\(i\\) 估一元 GARCH（或 EGARCH/GJR），得到 \\(\\hat\\sigma_{it}\\) 与标准化残差 \\(e_{it}=r_{it}/\\hat\\sigma_{it}\\)。边缘设定错误会进入第二步。</p><p><strong>第二步。</strong> 令 \\(Q_t\\) 为</p> \\[Q_t=(1-a-b)\\bar Q+a\\, e_{t-1}e_{t-1}&#39;+b\\, Q_{t-1}, \\]<p>其中 \\(\\bar Q\\) 是 \\(\\{e_t\\}\\) 的无条件协方差（常用样本矩，即相关目标对称）。约束 \\(a\\ge 0,\\ b\\ge 0,\\ a+b\\lt 1\\)。再</p> \\[R_t=\\mathrm{diag}(Q_t)^{-1/2}\\, Q_t\\, \\mathrm{diag}(Q_t)^{-1/2}. \\]<p>对角标准化强制 \\(R_{t,ii}=1\\)。\\(a\\) 大则相关对最近冲击敏感，\\(b\\) 大则相关缓慢移动。<span class="marginnote">数字实例：取 \\(a=0.05\\)、\\(b=0.90\\)，则 \\(a+b=0.95\\)，冲击后残留效应按 \\(b^k\\) 衰减，半衰期约 \\(\\ln 0.5/\\ln 0.9\\approx 6.6\\) 天——一次同跌冲击抬高的相关，一周后还剩一半。若 \\(b=0.98\\)，半衰期约 34 天，相关就会「粘」在危机高位很久。</span>两步准极大似然在正则条件下一致；联合一步估计更有效，但高维时数值差。</p><p>准似然在高斯新息下是真实似然；新息为 \\(t\\) 或有偏时，仍可作为准极大似然，相关动态的点估计往往还可用，标准误则应稳健。Engle 与 Sheppard 的工作论文把两步的渐近方差写清楚：第一步边缘的估计误差会进入 \\(a,b\\) 的标准误，不能把第二步当成 \\(e_t\\) 已知时的普通 MLE。</p><p>Cappiello、Engle 与 Sheppard 的非对称 DCC（ADCC）让负残差外积另进一项，允许下跌日相关跳得更狠。分组 DCC、因子 DCC 把 \\(a,b\\) 按行业或按因子载荷放开，缓解标量刚性。相关目标 \\(\\bar Q\\) 也可用衰减加权，让锚跟随近期体制，避免十年前的危机永远抬高平静期的 \\(R_t\\)。</p><h3 id="与-ccc、bekk、copula-的对照" tabindex="-1">与 CCC、BEKK、Copula 的对照 <a class="header-anchor" href="#与-ccc、bekk、copula-的对照" aria-label="Permalink to &quot;与 CCC、BEKK、Copula 的对照&quot;">​</a></h3><p>CCC 是 \\(a=b=0\\) 的特例，可用似然比检验。BEKK 保证正定，能产生方差与协方差的溢出，但参数多，适合很小的 \\(d\\)。DCC 不建模「\\(i\\) 的波动进 \\(j\\) 的方差」那种方差溢出，只建模相关；若问题是波动传染，DCC 不是对象。</p><p>椭圆新息下，DCC 的 \\(R_t\\) 即条件 Copula 的相关参数。新息有尾依赖时，DCC 仍只驱动二阶，<a href="/quant/copula">Copula</a> 的 \\(\\lambda\\) 不会因为 \\(\\rho_t\\) 升高而从 0 变成正。压力测试若只把 DCC 的 \\(R_t\\) 换成「危机相关」，仍可能低估同爆。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>标准化残差的外积 \\(e_{t-1}e_{t-1}&#39;\\) 在两资产同号大冲击时把 \\(Q_t\\) 的对应元抬高，随后以速率 \\(b\\) 向 \\(\\bar Q\\) 回复。这是相关的 GARCH：冲击来自共同的标准化意外，而不是来自原始收益的共同大波动。正定性由 \\(Q_t\\) 作为 GARCH 型递归在 \\(a,b\\) 约束下保持（给定 \\(\\bar Q\\) 正定），再经对角标准化传到 \\(R_t\\)。</p>',23)),(E(),i(_,null,{default:t(()=>[r(C,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E4%B8%A4%E8%B5%84%E4%BA%A7%E5%90%8C%E5%8F%B7%E5%A4%A7%E6%84%8F%E5%A4%96%3A%20e_i%20*%20e_j%20%E5%BE%88%E5%A4%A7%22%5D%20--%3E%20JUMP%5B%22Q_ij%20%E6%8A%AC%E9%AB%98%22%5D%0A%20%20JUMP%20--%3E%20NORM%5B%22%E5%AF%B9%E8%A7%92%E6%A0%87%E5%87%86%E5%8C%96%E5%90%8E%20R_ij%20%E5%8D%87%E5%90%91%E9%AB%98%E4%BD%8D%22%5D%0A%20%20NORM%20--%3E%20DECAY%5B%22%E6%AD%A4%E5%90%8E%E6%AF%8F%E5%A4%A9%E4%B9%98%20b%20%E5%90%91%E9%94%9A%20Qbar%20%E5%9B%9E%E8%90%BD%22%5D%0A%20%20DECAY%20--%3E%20HALF%7B%22%E5%8D%8A%E8%A1%B0%E6%9C%9F%E8%BF%87%E4%BA%86%E5%90%97%22%7D%0A%20%20HALF%20--%20%22%E6%B2%A1%E6%9C%89%2C%20%E4%BB%8D%E6%98%BE%E8%91%97%E9%AB%98%E4%BA%8E%E9%94%9A%22%20--%3E%20KEEP%5B%22%E7%9B%B8%E5%85%B3%E7%B2%98%E5%9C%A8%E9%AB%98%E4%BD%8D%3A%20%E5%88%86%E6%95%A3%E5%8C%96%E4%BB%8D%E5%A4%B1%E6%95%88%22%5D%0A%20%20HALF%20--%20%22%E6%98%AF%2C%20%E5%9B%9E%E5%88%B0%E5%B8%B8%E6%80%81%22%20--%3E%20BASE%5B%22R_ij%20%E5%9B%9E%E5%88%B0%20Qbar%20%E9%99%84%E8%BF%91%22%5D%0A%20%20OPPO%5B%22%E4%B8%A4%E8%B5%84%E4%BA%A7%E5%8F%8D%E5%8F%B7%E5%86%B2%E5%87%BB%22%5D%20--%3E%20DOWN%5B%22%E5%A4%96%E7%A7%AF%E4%B8%BA%E8%B4%9F%2C%20Q_ij%20%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<p>两步之所以能用，是因为在高斯准似然下，边缘方差参数与相关参数在信息矩阵上近似分块：先把 \\(D_t\\) 估对，再估 \\(R_t\\) 的损失主要是效率而非一致性。边缘若是错的（忽略偏度、跳跃），\\(e_t\\) 不是单位方差不相关新息，\\(Q_t\\) 跟踪的就不是「纯相关」。</p><p><span class="marginnote">\\(\\bar Q\\) 用全样本矩，是平滑相关的锚。样本含一次危机，锚会被抬高，平静期的 \\(R_t\\) 也会偏高。滚动或指数加权的目标相关，是工程补丁，会削弱「无条件均值」的解释，却常更适合交易。</span></p><h3 id="估计与检验里的陷阱" tabindex="-1">估计与检验里的陷阱 <a class="header-anchor" href="#估计与检验里的陷阱" aria-label="Permalink to &quot;估计与检验里的陷阱&quot;">​</a></h3><p>\\(a+b\\) 贴近 1 时相关近单位根，滤波极持久，样本外 \\(R_t\\) 会粘在危机后的高位。似然对 \\(a,b\\) 可能平坦。资产很多时，\\(\\bar Q\\) 的估计误差主导，需要对 \\(\\bar Q\\) 做收缩或因子结构。标准化残差应做 McLeod–Li 一类检查：若一元 GARCH 没吸干，DCC 会把剩余 ARCH 读成相关动态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>标量 DCC 强迫所有资产对同一 \\(a,b\\)。行业内相关与跨市场相关的回复速度可以差一个数量级。非对称、分组、因子 DCC 在放宽，也在增加过拟合。日频以下，不同步成交让同期 \\(e_{it}e_{jt}\\) 偏向 0，DCC 会低估高频相关，这是 Epps 效应，不是相关真的低。</p><p>不要把 \\(R_t\\) 的一个元素当成可交易的「相关溢价」信号而不做交易成本与滞后。不要用 DCC 协方差直接做最小方差组合却忽略估计误差——收缩、因子风险模型仍有位置。不要在有<a href="/quant/jump-tests">跳跃</a>的日子把 \\(e_t\\) 当高斯：一次跳会把 \\(Q_t\\) 打歪很多期。</p><p>与 EVT、Copula 叠用时，顺序应是：DCC 或一元 GARCH 过滤 → 残差做 Copula 或 GPD，而不是对 DCC 输出的相关矩阵再「乘一个厚尾系数」。相关是二阶对象，尾是 Copula 或极值对象。</p><p><span class="marginnote">Engle（2002）的标题写的是 simple class：简单是设计目标。它不是最一般的多元 GARCH，而是在可估计性约束下让相关动起来。用它替代 BEKK 去讲波动溢出，是问错了模型。</span></p>',9)),(E(),i(_,null,{default:t(()=>[r(C,{id:"mermaid-91",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%94%B6%E7%9B%8A%20r_t%22%5D%20--%3E%20G%5B%22%E4%B8%80%E5%85%83%20GARCH%20%E2%86%92%20%CF%83_it%22%5D%0A%20%20G%20--%3E%20E%5B%22%E6%A0%87%E5%87%86%E5%8C%96%E6%AE%8B%E5%B7%AE%20e_t%22%5D%0A%20%20E%20--%3E%20Q%5B%22Q_t%20%E5%9D%87%E5%80%BC%E5%9B%9E%E5%A4%8D%22%5D%0A%20%20Q%20--%3E%20RT%5B%22%E5%AF%B9%E8%A7%92%E6%A0%87%E5%87%86%E5%8C%96%E5%BE%97%20R_t%22%5D%0A%20%20G%20--%3E%20D%5B%22D_t%20%E5%AF%B9%E8%A7%92%22%5D%0A%20%20D%20--%3E%20H%5B%22H_t%20%3D%20D_t%20R_t%20D_t%22%5D%0A%20%20RT%20--%3E%20H%0A%20%20H%20--%3E%20USE%5B%22%E7%BB%84%E5%90%88%E9%A3%8E%E9%99%A9%20%2F%20%E5%AF%B9%E5%86%B2%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DCC 把条件协方差写成 \\(D_t R_t D_t\\)：一元 GARCH 管 \\(D_t\\)，低维动态管 \\(R_t\\)。</li><li>\\(Q_t\\) 对标准化残差外积做 GARCH 式回复，再标准化保证 \\(R_t\\) 是相关矩阵。</li><li>标量 DCC 参数少、可高维，但共用 \\(a,b\\)；CCC 是其冻结相关的特例。</li><li>它更新二阶相关，不产生尾依赖；与 Copula、EVT 互补而非替代。</li><li>边缘 GARCH 误设、不同步成交、\\(\\bar Q\\) 含危机，都会让 \\(R_t\\) 偏。</li><li>出处：Engle, <em>Journal of Business &amp; Economic Statistics</em>, 2002；两步渐近见 Engle and Sheppard 工作论文；CCC 见 Bollerslev, <em>Review of Economics and Statistics</em>, 1990；相近设定见 Tse and Tsui, <em>JBES</em>, 2002；非对称见 Cappiello, Engle, Sheppard, 2006。</li></ul>',2))])}const R=o(A,[["render",p]]);export{u as __pageData,R as default};
